static pj_xml_attr *alloc_attr( pj_pool_t *pool ) /* <=== alloc_attr */ 
{
    return PJ_POOL_ZALLOC_T(pool, pj_xml_attr);
}

static pj_xml_node *alloc_node( pj_pool_t *pool ) /* <=== alloc_node */ 
{
    pj_xml_node *node;

    node = PJ_POOL_ZALLOC_T(pool, pj_xml_node);
    pj_list_init( &node->attr_head );
    pj_list_init( &node->node_head );

    return node;
}

static void on_syntax_error(struct pj_scanner *scanner) /* <=== on_syntax_error */ 
{
    PJ_UNUSED_ARG(scanner);
    PJ_THROW(EX_SYNTAX_ERROR);
}

PJ_INLINE(int) pj_scan_is_eof( const pj_scanner *scanner) /* <=== pj_scan_is_eof */ 
{
    return scanner->curptr >= scanner->end;
}

